/* === ASD mobile redesign (activeShiftDash) === */
.activeShiftDash{--asd-done:#48bb78;--asd-work:#5b9cff;--asd-plan:#e8b84a}
.asdFolders{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.asdFolder.asdFolder--tile{
  appearance:none;cursor:pointer;text-align:left;font:inherit;color:inherit;
  min-height:0;max-height:none;height:auto;padding:0;overflow:visible;
  transition:transform .15s ease,border-color .15s ease,box-shadow .15s ease;
}
.asdFolder.asdFolder--tile:hover{
  transform:translateY(-1px);
  box-shadow:0 10px 24px rgba(0,0,0,.28);
}
.asdFolder.asdFolder--tile:active{transform:translateY(0)}
.asdFolder--tile header{
  display:flex;align-items:center;gap:8px;padding:12px 12px 4px;border:0;background:transparent;
}
.asdFolder--tile header h4{margin:0;flex:1;font-size:.78rem;font-weight:800;letter-spacing:.02em}
.asdFolder--tile header span{
  font-size:1.55rem;font-weight:800;font-variant-numeric:tabular-nums;line-height:1;min-width:1.4ch;text-align:right;
}
.asdFolder--done.asdFolder--tile{border-color:rgba(72,187,120,.4);background:linear-gradient(160deg,rgba(72,187,120,.18),rgba(0,0,0,.25))}
.asdFolder--done.asdFolder--tile header span{color:var(--asd-done)}
.asdFolder--work.asdFolder--tile{border-color:rgba(91,156,255,.4);background:linear-gradient(160deg,rgba(91,156,255,.18),rgba(0,0,0,.25))}
.asdFolder--work.asdFolder--tile header span{color:#7eb6ff}
.asdFolder--plan.asdFolder--tile{border-color:rgba(232,184,74,.4);background:linear-gradient(160deg,rgba(232,184,74,.16),rgba(0,0,0,.25))}
.asdFolder--plan.asdFolder--tile header span{color:var(--asd-plan)}
.asdFolderHint{margin:0 12px 12px;font-size:.68rem;opacity:.62;font-weight:600}

.asdFinance{border-radius:14px;border:1px solid rgba(255,255,255,.08);background:#00000038;padding:12px}
.asdFinance>header{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.asdFinance>header h4{margin:0;font-size:.85rem}
.asdFinanceGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.asdFinTile{
  display:flex;flex-direction:column;gap:4px;padding:10px 12px;border-radius:12px;
  border:1px solid rgba(255,255,255,.06);background:rgba(255,255,255,.04);min-width:0;
}
.asdFinTile span{font-size:.68rem;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--text-muted);display:inline-flex;align-items:center;gap:4px}
.asdFinTile strong{font-size:1.05rem;font-variant-numeric:tabular-nums;line-height:1.15}
.asdFinTile--revenue,.asdFinTile--income{border-color:rgba(72,187,120,.28);background:rgba(72,187,120,.1)}
.asdFinTile--loss{border-color:rgba(252,129,129,.22);background:rgba(252,129,129,.08)}
.asdExpenses{border-radius:14px;border:1px solid rgba(255,255,255,.08);background:#00000028;padding:12px;margin-top:10px}
.asdExpenses>header{display:flex;align-items:center;gap:8px;margin-bottom:8px}
.asdExpenses>header h4{margin:0;font-size:.85rem;flex:1}
.asdExpenseList{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;max-height:160px;overflow:auto}
.asdExpenseList li{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;align-items:center;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,.03);font-size:.78rem}
.asdExpenseList em{font-style:normal;color:var(--text-muted);font-size:.72rem}

.asdPeople{position:relative;overflow:hidden}
.asdPeople>header{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.asdPeople>header h4{margin:0;font-size:.9rem}
.asdPeople--drivers{border-color:rgba(240,180,41,.28);background:linear-gradient(180deg,rgba(240,180,41,.08),rgba(0,0,0,.22));box-shadow:inset 3px 0 0 #f0b429}
.asdPeople--disp{border-color:rgba(91,156,255,.28);background:linear-gradient(180deg,rgba(91,156,255,.1),rgba(0,0,0,.22));box-shadow:inset 3px 0 0 #5b9cff;margin-top:4px}
.asdPeopleList li{padding:10px;border-radius:12px;background:rgba(0,0,0,.22);border:1px solid rgba(255,255,255,.05)}
.asdPersonMeta b{color:var(--text);font-variant-numeric:tabular-nums}
.asdDispCard{backdrop-filter:blur(4px)}

.asdSpeetRoot{position:fixed;inset:0;z-index:12000;display:flex;align-items:flex-end;justify-content:center}
.asdSpeetBackdrop{position:absolute;inset:0;border:0;padding:0;margin:0;background:rgba(4,6,10,.72);cursor:pointer}
.asdSpeet{
  position:relative;z-index:1;width:min(560px,100%);max-height:min(78vh,720px);
  display:flex;flex-direction:column;border-radius:18px 18px 0 0;
  border:1px solid rgba(255,255,255,.1);border-bottom:0;
  background:linear-gradient(180deg,#151a22,#0b0e14 40%);
  box-shadow:0 -18px 48px rgba(0,0,0,.45);
  animation:asdSpeetIn .22s ease-out;
}
@keyframes asdSpeetIn{from{transform:translateY(18px);opacity:.6}to{transform:none;opacity:1}}
.asdSpeetHead{display:flex;align-items:center;gap:12px;padding:14px 16px 10px;border-bottom:1px solid rgba(255,255,255,.08)}
.asdSpeetHead h4{margin:0;flex:1;font-size:1rem;font-weight:800}
.asdSpeetClose{
  width:36px;height:36px;border-radius:10px;border:1px solid rgba(255,255,255,.12);
  background:rgba(255,255,255,.06);color:inherit;font-size:1.35rem;line-height:1;cursor:pointer;
}
.asdSpeet .asdOrderList,.asdSpeet .asdEmpty{padding:10px 12px 18px;overflow:auto;flex:1;max-height:none}
.asdSpeet .asdOrderList{list-style:none;margin:0;display:flex;flex-direction:column;gap:6px}
.asdSpeet .asdOrderList li{
  display:grid;grid-template-columns:auto minmax(0,1fr) auto auto;gap:8px;align-items:center;
  padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.05);
}

@media (max-width:900px){
  .asdLayout{grid-template-columns:1fr;gap:12px}
  .asdFolders{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
  .asdFinanceGrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .asdFinTile--revenue{grid-column:1/-1}
  .asdFinTile--revenue strong{font-size:1.35rem}
}
@media (max-width:520px){
  .asdFolders{grid-template-columns:1fr;gap:8px}
  .asdFolder--tile header span{font-size:1.8rem}
  .asdFolderHint{margin-bottom:10px}
  .asdHead{gap:10px}
  .asdFinanceGrid{gap:8px}
  .asdSpde{gap:10px}
  .asdSpeet{max-height:85vh;border-radius:16px 16px 0 0}
}

