/* === mileage asdM6 === */
.mileView{display:flex;flex-direction:column;gap:14px;padding:12px 14px 28px;max-width:1100px;margin:0 auto}
.mileHead{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-start;justify-content:space-between}
.mileHeadTitle{display:flex;gap:10px;align-items:flex-start}
.mileHeadIcon{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:rgba(240,180,41,.15);color:#f0b429}
.mileHead h2{margin:0;font-size:1.25rem}
.mileHead p{margin:2px 0 0;opacity:.7;font-size:.82rem;max-width:42ch}
.mileHeadTools{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.mileSeg{display:inline-flex;border:1px solid rgba(255,255,255,.14);border-radius:10px;overflow:hidden}
.mileSeg button{border:0;background:transparent;color:inherit;padding:8px 12px;font:inherit;cursor:pointer}
.mileSeg button.on{background:linear-gradient(180deg,#f0b429,#c48a12);color:#1a1205;font-weight:700}
.mileDate{border:1px solid rgba(255,255,255,.16);border-radius:10px;background:rgba(0,0,0,.25);color:inherit;padding:8px 10px;font:inherit}
.mileBtn{display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(255,255,255,.16);border-radius:10px;background:rgba(255,255,255,.06);color:inherit;padding:8px 12px;font:inherit;cursor:pointer}
.mileError{padding:10px 12px;border-radius:10px;background:rgba(231,76,60,.15);color:#ffb4a8}
.mileKpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.mileKpi{padding:10px 12px;border-radius:12px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08)}
.mileKpi span{display:block;font-size:.72rem;opacity:.7;margin-bottom:4px}
.mileKpi strong{font-size:1.05rem;font-variant-numeric:tabular-nums}
.mileKpi strong.neg{color:#fc8181}
.mileKpi strong.pos{color:#7dcea0}
.mileTableWrap{overflow:hidden;border-radius:14px;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.18)}
.mileTable{width:100%;border-collapse:collapse;min-width:0;table-layout:fixed;font-size:.8rem}
.mileTable th,.mileTable td{padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08);border-right:1px dashed rgba(255,255,255,.22);text-align:left;vertical-align:top}
.mileTable th:last-child,.mileTable td:last-child{border-right:none}.mileTable th{position:sticky;top:0;background:rgba(20,22,28,.96);font-size:.72rem;text-transform:uppercase;letter-spacing:.04em;opacity:.85;z-index:1}
.mileTable td.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
.mileTable td.num.neg{color:#fc8181;font-weight:700}
.mileTable td.num.pos{color:#7dcea0}
.mileDateCell b{display:block}
.mileDateCell i{font-style:normal;opacity:.65;font-size:.75rem}
.mileDriverCell{min-width:0;white-space:normal}
.mileDriverCell strong,.mileDriverCell span{display:block;line-height:1.25;white-space:normal;overflow-wrap:anywhere}
.mileDriverCell strong{font-weight:800;font-size:.82rem;color:#f3f6fb}
.mileDriverCell span{margin-top:2px;opacity:.72;font-size:.7rem;color:#9aa6b8}
.mileTable td.num em{display:block;font-style:normal;opacity:.6;font-size:.72rem;font-weight:400}
.mileEmpty{text-align:center;opacity:.7;padding:28px 12px!important}
.mileHint{margin:0;opacity:.65;font-size:.78rem;line-height:1.4}
@media (max-width:720px){
  .mileView{padding:10px 10px 24px}
