}

/* === fuel table asdM7 === */
.ccFuelCol{width:680px;max-width:680px}
.ccFuelCols--focus .ccFuelCol{width:100%;max-width:none}
.ccFuelColTable{table-layout:fixed;width:100%;font-size:.72rem}
.ccFuelColTable th,.ccFuelColTable td{padding:6px 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;vertical-align:middle;line-height:1.2}
.ccFuelColTable th:nth-child(1),.ccFuelColTable td:nth-child(1){width:52px}
.ccFuelColTable th:nth-child(2),.ccFuelColTable td:nth-child(2){width:44px}
.ccFuelColTable th:nth-child(3),.ccFuelColTable td:nth-child(3){width:52px}
.ccFuelColTable th:nth-child(4),.ccFuelColTable td:nth-child(4),
.ccFuelColTable th:nth-child(5),.ccFuelColTable td:nth-child(5),
.ccFuelColTable th:nth-child(7),.ccFuelColTable td:nth-child(7){width:72px}
.ccFuelColTable th:nth-child(6),.ccFuelColTable td:nth-child(6){width:58px}
.ccFuelColTable th:nth-child(8),.ccFuelColTable td:nth-child(8){width:78px}
.ccFuelColTable td.ccNum.neg,.ccFuelColTable td.neg{color:#fc8181;font-weight:700}
.ccFuelColTable td.ccNum.pos,.ccFuelColTable td.pos{color:#7dcea0}
.ccFuelBalCell{display:none}
@media (max-width:720px){
  .ccFuelCol{width:min(680px,92vw);max-width:min(680px,92vw)}
  .ccFuelColTable{font-size:.68rem}
}

