.fixLog{width:min(1180px,100%)!important;max-height:min(92vh,900px)!important;padding:18px 18px 14px!important;display:flex;flex-direction:column}
.fixKpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-bottom:12px}
.fixTools{display:flex;flex-direction:column;gap:10px;margin-bottom:12px}
.fixSeg{align-self:flex-start}
.fixDayChips{margin:0!important}
.fixDayChips .dtlDay u{display:block;margin-top:2px;font-size:10px;font-weight:750;text-decoration:none;opacity:.75}
