.fixScroll{overflow:auto;flex:1;min-height:0;padding-right:2px}
.fixBlocks{display:flex;flex-direction:column;gap:14px}
.fixDayCard{border:1px solid var(--border);border-radius:18px;background:var(--sink-1);overflow:hidden}
.fixDayHead{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;background:var(--surface-2);border-bottom:1px solid var(--border);flex-wrap:wrap}
.fixDayDate{display:flex;align-items:baseline;gap:8px}
.fixDayDate b{font-size:1.35rem;line-height:1;font-weight:800}
.fixDayDate span{font-size:.8rem;color:var(--text-muted)}
.fixDayMeta{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:.78rem;color:var(--text-muted)}
.fixDayMeta strong{font-size:.95rem;color:var(--text)}
.fixTag{padding:2px 8px;border-radius:999px;border:1px solid var(--border-strong);font-weight:700}
.fixTag.partner{color:#c4b5fd;border-color:rgba(167,139,250,.45);background:rgba(167,139,250,.14)}
.fixTag.cancel{color:#fca5a5;border-color:rgba(248,113,113,.45);background:rgba(248,113,113,.14)}
.fixTableWrap{overflow-x:auto}
