.fixTable th,.fixTable td{padding:9px 10px;border-bottom:1px solid var(--border);text-align:left;white-space:nowrap;vertical-align:middle}
.fixTable thead th{background:var(--sink-1);font-weight:700;color:var(--text-muted);position:sticky;top:0;z-index:1}
.fixTable tbody tr:last-child td{border-bottom:0}
