.fixRow.partner td{background:rgba(167,139,250,.07)}
.fixRow.partner:hover td{background:rgba(167,139,250,.13)}
.fixTime b{display:block;font-weight:750}
.fixTime i{font-style:normal;font-size:10px;color:var(--text-muted)}
.fixShift{padding:2px 8px;border-radius:999px;font-size:11px;font-weight:700;border:1px solid var(--border-strong);color:var(--text-muted)}
.fixShift.day{color:#fcd34d;border-color:rgba(252,211,77,.4);background:rgba(252,211,77,.12)}
.fixShift.night{color:#93c5fd;border-color:rgba(147,197,253,.4);background:rgba(147,197,253,.12)}
.fixVeh{font-weight:700}
.fixCar,.fixPay{color:var(--text-muted)}
.fixStatus{padding:2px 8px;border-radius:999px;font-size:11px;font-weight:700;border:1px solid var(--border-strong);color:var(--text-muted)}
.fixStatus--completed{color:#6ee7b7;border-color:rgba(52,211,153,.4);background:rgba(52,211,153,.12)}
.fixStatus--in_progress{color:#fcd34d;border-color:rgba(252,211,77,.4);background:rgba(252,211,77,.12)}
.fixStatus--cancelled{color:#fca5a5;border-color:rgba(248,113,113,.4);background:rgba(248,113,113,.12)}
.fixStatus--scheduled{color:#93c5fd;border-color:rgba(147,197,253,.4);background:rgba(147,197,253,.12)}
.fixPaid{margin-left:6px;padding:2px 7px;border-radius:999px;font-size:10px;font-weight:700;color:#6ee7b7;border:1px solid rgba(52,211,153,.35);background:rgba(52,211,153,.1)}
.fixAmt{text-align:right!important}
.fixAmt b{font-weight:750}
.fixAmt i{display:block;font-style:normal;font-size:10px;color:var(--text-muted)}
@media (max-width:900px){
  .fixKpis{grid-template-columns:repeat(2,minmax(0,1fr))}
  .fixDayHead{flex-direction:column;align-items:flex-start}
}

/* ===== asdMD: cash summary + fuel cards + fixation ===== */
.ccSumTiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px;padding:12px}
.ccSumTile{display:flex;flex-direction:column;gap:6px;padding:14px 16px;border-radius:16px;border:1px solid var(--border);background:var(--sink-1,rgba(0,0,0,.22));box-shadow:var(--shadow-soft)}
.ccSumTileLb{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted)}
.ccSumTileVal{font-size:23px;font-weight:800;line-height:1.1;letter-spacing:-.4px;font-variant-numeric:tabular-nums}
.ccSumTileBy{display:flex;flex-wrap:wrap;gap:4px 10px;font-style:normal;font-size:11px;color:var(--text-muted)}
.ccSumTileBy em{font-style:normal;font-variant-numeric:tabular-nums}
.ccSumTile--bal{border-color:#f0b42959;background:linear-gradient(180deg,rgba(240,180,41,.12),transparent 72%)}
.ccSumTile--bal .ccSumTileVal{color:var(--yellow-text,#ffe7a8)}
.ccSumTile--in .ccSumTileVal{color:var(--green-text,#86efac)}
.ccSumTile--out .ccSumTileVal{color:var(--red,#f87171)}
.ccSumCards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px;padding:0 12px 12px}
.ccSumCard{border:1px solid var(--border);border-radius:16px;background:var(--sink-1,rgba(0,0,0,.22));overflow:hidden}
.ccSumCard>header{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:10px 14px;border-bottom:1px solid var(--border)}
.ccSumCard>header b{font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.ccSumCard>header strong{font-size:16px;font-weight:800;font-variant-numeric:tabular-nums}
.ccSumCard.in>header strong{color:var(--green-text,#86efac)}
.ccSumCard.out>header strong{color:var(--red,#f87171)}
.ccSumCard.bal>header strong{color:var(--yellow-text,#ffe7a8)}
.ccSumCard ul{list-style:none;margin:0;padding:6px}
.ccSumRow{display:flex;align-items:baseline;gap:10px;padding:7px 8px;font-size:12.5px}
.ccSumRow+.ccSumRow{border-top:1px solid color-mix(in srgb,var(--border) 70%,transparent)}
.ccSumRowLb{flex:0 0 auto;min-width:72px;color:var(--text-muted);font-weight:700}
.ccSumRow em{font-style:normal;font-size:11.5px;color:var(--text-muted);font-variant-numeric:tabular-nums}
.ccSumRow b{margin-left:auto;font-weight:800;font-variant-numeric:tabular-nums}
.ccSumOps{border-top:1px solid var(--border);padding:10px 12px}
.ccSumOpsHead{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:8px}
.ccSumOpsHead b{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.ccSumOpsHead span{font-size:11px;color:var(--text-muted)}
.ccSumOpsList{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px;max-height:340px;overflow:auto}
.ccSumOp{display:grid;grid-template-columns:62px minmax(0,1fr) auto auto;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--border);border-radius:12px;background:var(--bg-card,#121820)}
.ccSumOpDate{display:flex;flex-direction:column;line-height:1.15}
.ccSumOpDate b{font-size:12.5px;font-variant-numeric:tabular-nums}
.ccSumOpDate i{font-style:normal;font-size:10.5px;color:var(--text-muted)}
.ccSumOpWho{display:flex;flex-direction:column;min-width:0;line-height:1.2}
.ccSumOpWho b{font-size:12.5px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccSumOpWho i{font-style:normal;font-size:10.5px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccSumOpCh{font-size:10.5px;font-weight:700;padding:3px 8px;border-radius:999px;border:1px solid var(--border);color:var(--text-muted);white-space:nowrap}
.ccSumOpCh--cash{color:var(--green-text,#86efac);border-color:#3dd68c40}
.ccSumOpCh--bank{color:var(--blue-text,#93c5fd);border-color:#60a5fa40}
.ccSumOpAmt{font-size:14px;font-weight:800;text-align:right;font-variant-numeric:tabular-nums}
.ccSumFoot{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 14px;padding:12px 14px;border-top:1px solid var(--border)}
.ccSumFootTotal{font-size:12.5px;color:var(--text-muted)}
.ccSumFootTotal strong{margin-left:6px;font-size:18px;font-weight:800;color:var(--yellow-text,#ffe7a8);font-variant-numeric:tabular-nums}
.ccSumFootMeta{font-size:11.5px;color:var(--text-muted);font-variant-numeric:tabular-nums}
.ccSumFootAct{margin-left:auto}
.ccFuelCols{grid-template-columns:repeat(auto-fill,minmax(360px,1fr))!important;width:100%!important;gap:12px;padding:12px}
.ccFuelCol{width:auto!important;border:1px solid var(--border)!important;border-radius:16px;background:var(--bg-card,#121820);overflow:hidden}
.ccFuelCols.ccFuelCols--focus{grid-template-columns:minmax(0,1fr)!important}
.ccFuelColHead{padding:12px 14px 10px!important;background:linear-gradient(180deg,rgba(240,180,41,.1),transparent)!important}
.ccFuelColName{font-size:14px;font-weight:800}
.ccFuelColTable{font-size:12px!important}
.ccFuelColTable th{background:var(--sink-2,rgba(0,0,0,.28))!important;font-size:10.5px!important;text-transform:uppercase;letter-spacing:.3px}
.ccFuelColTable tbody tr:nth-child(2n){background:rgba(255,255,255,.02)}
.ccFuelColTable .ccNum.neg{color:var(--red,#f87171)}
.ccFuelColTable .ccNum.pos{color:var(--green-text,#86efac)}
.fixKpis{grid-template-columns:repeat(auto-fit,minmax(150px,1fr))!important}
.fixTag.ours{color:var(--yellow-text,#ffe7a8);border-color:#f0b42959}

/* ===== asdME: frozen column fix, deal popup car, peak hour ===== */
.dealMtxTable thead th{background:#141820!important}
.dealMtxSticky{background:#141820!important;box-shadow:1px 0 0 var(--border)}
.dealMtxTable thead .dealMtxSticky{z-index:4!important}
.dealMtxTable tbody .dealMtxSticky{z-index:2!important;background:var(--bg-card,#121820)!important}
.dealMtxTable tbody tr:hover .dealMtxSticky{background:var(--bg-hover,#1a2230)!important}
.dealMtxScroll{overscroll-behavior:contain}
.fixTable thead th{background:#141820!important}
@media (max-width:720px){
  .dealMtxSticky{min-width:104px!important;max-width:124px!important;padding-left:8px!important}
}
.dealPopOrders li{grid-template-columns:minmax(0,1fr) 46px 60px auto}
.dealPopOrderCar{display:flex;flex-direction:column;min-width:0;line-height:1.2}
.dealPopOrderCar i{font-style:normal;font-size:10.5px;font-weight:600;color:var(--text-muted)}
.fixPeakHero{position:relative;display:grid;grid-template-columns:minmax(0,auto) minmax(0,1fr);grid-template-areas:"main bars" "top top";align-items:end;gap:10px 18px;margin-bottom:12px;padding:16px 18px 14px;border:1px solid var(--border);border-radius:24px 24px 120px 120px/24px 24px 48px 48px;background:radial-gradient(120% 160% at 0% 0%,rgba(240,180,41,.16),transparent 60%),var(--sink-1,rgba(0,0,0,.22));overflow:hidden}
.fixPeakMain{grid-area:main;display:flex;flex-direction:column;gap:2px;min-width:0}
.fixPeakLb{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted)}
.fixPeakVal{font-size:30px;font-weight:800;line-height:1.05;letter-spacing:-.6px;color:var(--yellow-text,#ffe7a8);font-variant-numeric:tabular-nums}
.fixPeakSub{font-size:12px;color:var(--text-muted);font-variant-numeric:tabular-nums}
.fixPeakBars{grid-area:bars;display:flex;align-items:flex-end;gap:2px;height:58px;min-width:0}
.fixPeakBar{flex:1 1 0;min-width:2px;border-radius:3px 3px 0 0;background:rgba(255,255,255,.14)}
.fixPeakBar.on{background:var(--accent,#f0b429);box-shadow:0 0 12px rgba(240,180,41,.5)}
.fixPeakTop{grid-area:top;display:flex;flex-wrap:wrap;gap:6px}
.fixPeakChip{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;border:1px solid var(--border);font-size:11px;color:var(--text-muted);font-variant-numeric:tabular-nums}
.fixPeakChip b{color:var(--text);font-weight:800}
.fixViewSeg{align-self:flex-start}
.fixHours{display:flex;flex-direction:column;gap:10px}
.fixHoursHead{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
.fixHoursHead b{font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.fixHoursHead span{font-size:11.5px;color:var(--text-muted)}
.fixHoursList{display:flex;flex-direction:column;gap:4px}
.fixHourRow{display:grid;grid-template-columns:52px minmax(0,1fr) 72px 92px 96px;align-items:center;gap:10px;padding:7px 10px;border:1px solid transparent;border-radius:12px;font-size:12.5px}
.fixHourRow.on{border-color:#f0b42959;background:rgba(240,180,41,.1)}
.fixHourRow.empty{opacity:.42}
.fixHourLb{font-weight:800;font-variant-numeric:tabular-nums;color:var(--text-muted)}
.fixHourRow.on .fixHourLb{color:var(--yellow-text,#ffe7a8)}
.fixHourBarWrap{height:10px;border-radius:999px;background:rgba(255,255,255,.06);overflow:hidden}
.fixHourBar{display:block;height:100%;border-radius:999px;background:linear-gradient(90deg,rgba(240,180,41,.55),var(--accent,#f0b429))}
.fixHourNum{font-size:11.5px;color:var(--text-muted);font-variant-numeric:tabular-nums;text-align:right}
.fixHourDone{color:var(--green-text,#86efac)}
.fixHourSum{font-weight:800;text-align:right;font-variant-numeric:tabular-nums}
@media (max-width:720px){
  .fixPeakHero{grid-template-columns:minmax(0,1fr);grid-template-areas:"main" "bars" "top";align-items:stretch;border-radius:22px}
  .fixPeakBars{height:44px}
  .fixHourRow{grid-template-columns:46px minmax(0,1fr) auto;grid-template-areas:"lb bar sum" "lb num done";row-gap:2px}
  .fixHourLb{grid-area:lb}
  .fixHourBarWrap{grid-area:bar}
  .fixHourSum{grid-area:sum}
  .fixHourNum{grid-area:num;text-align:left}
  .fixHourDone{grid-area:done;text-align:right}
}

/* ===== asdMF: fuel / wash sheet ===== */
.ccFuelCols{grid-template-columns:repeat(auto-fill,minmax(460px,1fr))!important}
.ccFuelBody{display:flex;flex-direction:column;gap:8px;padding:10px 12px 12px}
.ccFuelTiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(88px,1fr));gap:6px}
.ccFuelTile{display:flex;flex-direction:column;gap:1px;padding:8px 10px;border:1px solid var(--border);border-radius:12px;background:var(--sink-2,rgba(0,0,0,.28))}
.ccFuelTile span{font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.ccFuelTile strong{font-size:14px;font-weight:800;font-variant-numeric:tabular-nums}
.ccFuelTile i{font-style:normal;font-size:10px;color:var(--text-muted);font-variant-numeric:tabular-nums}
.ccFuelTile.pos strong{color:var(--green-text,#86efac)}
.ccFuelTile.neg strong{color:var(--red,#f87171)}
.ccFuelHeadRow,.ccFuelRow{display:grid;grid-template-columns:96px 104px 118px minmax(0,1.25fr) 84px 108px 116px;gap:8px}
.ccFuelHeadRow{padding:4px 10px;border-bottom:1px solid var(--border)}
.ccFuelHeadRow span{font-size:9.5px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.ccFuelRows{display:flex;flex-direction:column;gap:6px}
.ccFuelRow{align-items:start;padding:9px 10px;border:1px solid var(--border);border-radius:14px;background:var(--sink-1,rgba(0,0,0,.22));font-variant-numeric:tabular-nums}
.ccFuelRow.idle{opacity:.5}
.ccFuelCell{display:flex;flex-direction:column;gap:2px;min-width:0}
.ccFuelCell b{font-size:12.5px;font-weight:800}
.ccFuelCell i{font-style:normal;font-size:10px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ccFuelCell u{text-decoration:none;font-size:9.5px;color:var(--text-muted)}
.ccFuelCell b.neg{color:var(--red,#f87171)}
.ccFuelCell b.pos{color:var(--green-text,#86efac)}
.ccFuelCellKm{gap:1px}
.ccFuelCellKm span{font-size:10px;color:var(--text-muted);display:flex;justify-content:space-between;gap:6px}
.ccFuelCellKm span b{font-size:11.5px;color:var(--text)}
.ccFuelMini{margin-top:2px;align-self:flex-start;padding:2px 8px;border-radius:999px;border:1px solid #f0c14d59;background:#f0c14d1f;color:var(--yellow-text,#ffe7a8);font-size:10px;font-weight:800;cursor:pointer;white-space:nowrap}
.ccFuelMini:hover{background:#f0c14d33}
@media (max-width:900px){
  .ccFuelCols{grid-template-columns:minmax(0,1fr)!important}
  .ccFuelHeadRow{display:none}
  .ccFuelRow{grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr);grid-template-areas:"date issue check" "km km km" "norm bal over";row-gap:8px}
  .ccFuelCellDate{grid-area:date}
  .ccFuelCellIssue{grid-area:issue}
  .ccFuelCellCheck{grid-area:check}
  .ccFuelCellKm{grid-area:km;flex-direction:row;gap:10px;flex-wrap:wrap}
  .ccFuelCellKm span{flex-direction:column;gap:0}
  .ccFuelCellNorm{grid-area:norm}
  .ccFuelCellBal{grid-area:bal}
  .ccFuelCellOver{grid-area:over}
}

/* ===== asdMG: off-hours accounting ===== */
.fixOff{display:block;font-style:normal;font-size:9.5px;font-weight:700;color:var(--red,#f87171);text-decoration:none}
.dealMtxCell.off{border-color:#f0b42959!important;background:rgba(240,180,41,.14)!important;color:var(--yellow-text,#ffe7a8)!important}
.dealMtxCell.off:hover{background:rgba(240,180,41,.24)!important}
.dealMtxMode button.on{background:#f0c14d24;color:var(--yellow-text,#ffe7a8)}
.offHoursNote{margin:4px 0 0;font-size:11.5px;font-weight:700;color:var(--red,#f87171)}

/* ===== asdMH: cash register in the shift-journal language ===== */
.xlCashColumn{gap:12px}
.xlCash{border:1px solid var(--border);border-radius:14px;overflow:hidden;background:var(--bg-card,rgba(0,0,0,.18))}
.xlCashTitle{position:relative;padding:10px 12px 10px 16px;background:var(--bg-elevated,#1a2030);color:var(--text);font-size:.7rem;font-weight:800;text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--border)}
