.xlBlockHead{padding:7px 12px;background:transparent;color:var(--text-muted);font-size:.62rem;font-weight:800;text-transform:uppercase;letter-spacing:.05em}
.xlBlock--income .xlBlockHead{background:transparent;color:var(--green-text,#86efac)}
.xlBlock--expense .xlBlockHead{background:transparent;color:var(--red-text,#fca5a5)}
.xlBlock--balance .xlBlockHead{background:#f0c14d14;color:var(--yellow-text,#ffe7a8)}
.xlHandHead{background:#f0c14d0f!important;color:var(--text-muted)!important;text-align:left!important}
.xlTriple{border-top:1px solid color-mix(in srgb,var(--border) 50%,transparent)}
.xlCol{border-right:1px solid color-mix(in srgb,var(--border) 55%,transparent);padding:8px 12px;min-height:46px}
.xlLab{margin-bottom:3px;font-size:.58rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--text-muted);opacity:1}
.xlVal{font-size:.95rem}
.xlBlock--income .xlVal{color:var(--green-text,#86efac)}
.xlBlock--expense .xlVal{color:var(--red-text,#fca5a5)}
.xlBlock--balance .xlVal{color:var(--yellow-text,#ffe7a8)}
.xlHandLog{border-top:1px solid color-mix(in srgb,var(--border) 70%,transparent);padding:10px 12px 12px}
.xlHandLogTitle{margin-bottom:8px;padding:6px 10px;border:1px solid var(--border);border-radius:8px;background:transparent;color:var(--text-muted);font-size:.62rem;font-weight:800;text-transform:uppercase;letter-spacing:.05em}
