.kbHandInCell b{font-size:.85rem;font-weight:800;font-variant-numeric:tabular-nums}
.kbEmpty{padding:14px 12px;text-align:center;border:1px dashed var(--border);border-radius:12px;color:var(--text-muted);font-size:.72rem}
