/* ===== asdMP: fuel matrix — one driver = two columns ===== */
.fmScroll{overflow:auto;max-width:100%;max-height:min(72vh,760px);border:1px solid var(--border);border-radius:14px;background:var(--bg-card,rgba(255,255,255,.02));-webkit-overflow-scrolling:touch}
