.fmTable th,.fmTable td{padding:0;text-align:left;vertical-align:top}
.fmTable thead th{position:sticky;top:0;z-index:3;background:var(--bg-elevated,#141a24);border-bottom:1px solid var(--border)}
.fmCorner{position:sticky;left:0;z-index:5;min-width:96px;width:96px;padding:10px 12px;font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted);border-right:1px solid var(--border)}
