.fmDrv i{display:block;margin-top:1px;font-style:normal;font-size:9.5px;color:var(--text-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:250px}
.fmDrv.on{background:#f0c14d14;box-shadow:inset 0 -2px 0 var(--accent,#f0b429)}
.fmHead2 th{top:46px;padding:5px 12px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted);border-left:1px solid color-mix(in srgb,var(--border) 55%,transparent)}
.fmHead2 th:nth-child(odd){border-left:1px solid var(--border)}
.fmDate{position:sticky;left:0;z-index:2;min-width:96px;width:96px;padding:9px 12px;background:var(--bg-elevated,#141a24);border-right:1px solid var(--border);border-bottom:1px solid var(--border)}
.fmDate b{display:block;font-size:12.5px;font-weight:800}
.fmDate i{font-style:normal;font-size:9.5px;text-transform:uppercase;letter-spacing:.3px;color:var(--text-muted)}
.fmRow td{padding:8px 12px 2px;border-left:1px solid color-mix(in srgb,var(--border) 55%,transparent)}
