.fxDate b{display:block;font-size:12.5px}
.fxDate i{display:block;font-style:normal;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.fxTable tbody tr:nth-child(even) td{background:color-mix(in srgb,#fff 1.6%,transparent)}
.fxTable tbody tr:hover td{background:color-mix(in srgb,var(--accent,#f0b429) 6%,transparent)}
.fxIss{min-width:104px;border-left:2px solid var(--border)}
.fxChk{min-width:112px}
.fxSep{border-left:1px dashed color-mix(in srgb,var(--border) 75%,transparent)}
.fxOff{background:repeating-linear-gradient(135deg,transparent,transparent 6px,color-mix(in srgb,var(--border) 22%,transparent) 6px,color-mix(in srgb,var(--border) 22%,transparent) 7px)}
.fxIss b,.fxChk b{display:block;font-size:13px;font-weight:800;white-space:nowrap}
.fxChk u{display:inline-block;margin-top:2px;padding:1px 6px;border-radius:99px;font-size:8.5px;text-decoration:none;text-transform:uppercase;letter-spacing:.4px;background:var(--sink-1,rgba(0,0,0,.24));color:var(--text-muted)}
.fxKm{display:block;margin-top:4px;font-style:normal;font-size:9.5px;color:var(--text-muted);white-space:nowrap}
.fxKm.warn{color:var(--red-text,#fca5a5);opacity:.85}
.fxBal{display:block;margin-top:4px;font-style:normal;font-size:10px;font-weight:800;white-space:nowrap}
.fxBal.pos{color:var(--green-text,#7ee2b8)}
.fxBal.neg{color:var(--red-text,#fca5a5)}
.fxPlus{display:inline-flex;align-items:center;justify-content:center;width:26px;height:24px;border:1px dashed color-mix(in srgb,var(--border) 90%,transparent);border-radius:8px;background:transparent;color:var(--text-muted);font-size:14px;line-height:1;cursor:pointer}
.fxPlus:hover{border-style:solid;border-color:var(--accent,#f0b429);color:var(--accent,#f0b429)}
.fxTable tfoot th,.fxTable tfoot td{background:var(--bg-elevated,#141a24);border-top:1px solid var(--border)}
.fxTable tfoot .fxDate{font-size:10px;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted)}
.fxSpan{border-left:2px solid var(--border)}
.fxSpan b{display:block;font-size:12.5px;font-weight:800}
.fxSpan b.pos{color:var(--green-text,#7ee2b8)}
.fxSpan b.neg{color:var(--red-text,#fca5a5)}
.fxSpan i{display:block;margin-top:2px;font-style:normal;font-size:9.5px;color:var(--text-muted);white-space:nowrap}
.fxTotMoney td b{font-size:13.5px}
.fxEmpty{padding:20px 12px;text-align:center;font-size:12px;color:var(--text-muted)}
@media (max-width:900px){
  .fxWrap{padding:10px}
  .fxTable th,.fxTable td{padding:7px 9px}
  .fxCorner,.fxDate{width:64px;min-width:64px;padding-left:8px;padding-right:8px}
  .fxDrv{min-width:176px}
  .fxIss{min-width:88px}
  .fxChk{min-width:96px}
  .fxH2 th{top:41px}
}

/* приём кассы — самостоятельный блок под промежуточной кассой */
.kbCash.kbAccept{margin-top:2px;border-color:color-mix(in srgb,var(--accent,#f0b429) 34%,var(--border))}
.kbCash.kbAccept .kbHandInRow{padding:10px 12px}
.kbCash.kbAccept .kbAcceptBtn{margin:0 12px 12px;width:calc(100% - 24px)}

/* ===== asdMZ: «+» в заполненных и пустых клетках матрицы ===== */
.fxPlus.more{width:20px;height:18px;margin-top:5px;font-size:11px;opacity:.35}
.fxTable tbody tr:hover .fxPlus.more{opacity:.9}
.fxPlus.more:hover{opacity:1}
.fxOff{vertical-align:middle}
.fxOff .fxPlus.more{margin-top:0}

/* ===== Топливо / мойка — единая таблица (дизайн по макету) ===== */
.tmWrap{
  --tm-panel:#10141a;--tm-panel2:#151a21;--tm-line:#2a313b;--tm-muted:#8b95a5;
  --tm-accent:#f5b72f;--tm-group:#0c1015;--tm-row:#10141a;--tm-rowh:#121820;
  --tm-text:#edf1f7;--tm-bad:#ff9b9b;--tm-badbg:rgba(220,70,70,.12);--tm-good:#b9e8c5;
  padding:14px;min-width:0;max-width:100%;color:var(--tm-text)
}
.tmNum,.tmTable,.tmKpiVal{font-variant-numeric:tabular-nums}

/* KPI */
.tmKpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin-bottom:14px}
.tmKpi{border:1px solid var(--tm-line);border-radius:12px;background:var(--tm-panel);padding:11px 12px;min-width:0}
.tmKpiLb{font-size:11px;line-height:1.3;color:var(--tm-muted)}
.tmKpiVal{margin-top:4px;font-size:20px;font-weight:700;letter-spacing:-.01em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tmKpi.bad .tmKpiVal{color:var(--tm-bad)}
.tmKpi.good .tmKpiVal{color:var(--tm-good)}
.tmKpi.accent .tmKpiVal{color:var(--tm-accent)}

/* подпись над таблицей */
.tmNote{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px;font-size:11.5px;color:var(--tm-muted)}
.tmNote b{color:#cbd5e1;font-weight:700}

/* таблица */
.tmScroll{overflow-x:auto;border:1px solid var(--tm-line);border-radius:16px;background:var(--tm-panel);box-shadow:0 18px 50px rgba(0,0,0,.35);-webkit-overflow-scrolling:touch}
.tmScroll::-webkit-scrollbar{height:10px}
.tmScroll::-webkit-scrollbar-track{background:#0a0d11}
.tmScroll::-webkit-scrollbar-thumb{background:#303846;border-radius:999px}
.tmTable{width:100%;min-width:1980px;border-collapse:collapse;font-size:12px}

.tmTable thead .tmG th{background:var(--tm-group);border-bottom:1px solid var(--tm-line);border-right:1px solid var(--tm-line);padding:11px 12px;text-align:center;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--tm-muted)}
.tmTable thead .tmG th:last-child{border-right:0}
.tmTable thead .tmG th.tmSticky{text-align:left}
.tmTable thead .tmG2 th{background:#0d1117;border-bottom:1px solid var(--tm-line);border-right:1px solid var(--tm-line);padding:9px 8px;text-align:center;font-size:11px;font-weight:600;line-height:1.25;color:var(--tm-muted)}
.tmTable thead th.tmSticky{position:sticky;left:0;z-index:30;background:var(--tm-group)}
.tmTable tbody td.tmSticky{position:sticky;left:0;z-index:15;background:var(--tm-row)}
.tmTable tbody tr:hover td.tmSticky{background:var(--tm-rowh)}
.tmHeadPlus{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;margin-left:5px;border:0;border-radius:5px;background:var(--tm-accent);color:#000;font-weight:800;font-size:13px;line-height:1;cursor:pointer;vertical-align:middle}
.tmHeadPlus:hover{filter:brightness(1.1)}

.tmTable tbody tr{background:var(--tm-row);border-bottom:1px solid color-mix(in srgb,var(--tm-line) 80%,transparent)}
.tmTable tbody tr:hover{background:var(--tm-rowh)}
.tmTable tbody td{border-right:1px solid var(--tm-line);padding:8px 10px;vertical-align:middle}
.tmTable tbody td:last-child{border-right:0}
.tmNum{text-align:center;font-weight:600}
.tmBig{font-size:13px;font-weight:700}
.tmDim{color:var(--tm-muted)}
.tmWarn{display:block;margin-top:2px;font-size:9.5px;font-weight:600;color:var(--tm-bad);opacity:.85}

.tmDateCell{border-right:1px solid var(--tm-line)}
.tmDate{display:flex;align-items:center;gap:6px}
.tmDate b{font-size:13px;font-weight:700}
.tmPeriod{font-style:normal;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;padding:2px 6px;border-radius:999px;background:rgba(245,183,47,.13);color:var(--tm-accent)}
.tmPeriod.night{background:rgba(120,150,255,.12);color:#9fb4ff}
.tmDrv{display:block;margin-top:3px;padding:0;border:0;background:none;color:var(--tm-muted);font-size:10.5px;text-align:left;cursor:pointer;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tmDrv:hover{color:var(--tm-accent)}

.tmMoneyCell{display:flex;align-items:center;justify-content:center;gap:6px}
.tmMoneyCell b{font-size:13px;font-weight:700}
.tmPlus{display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;flex:0 0 auto;border:0;border-radius:6px;background:var(--tm-accent);color:#000;font-weight:800;font-size:14px;line-height:1;cursor:pointer}
.tmPlus:hover{filter:brightness(1.1)}

.tmChkBtn{display:block;width:100%;padding:7px 9px;border:1px solid var(--tm-line);border-radius:9px;background:var(--tm-group);color:inherit;text-align:left;cursor:pointer}
.tmChkBtn:hover{border-color:#66501d}
.tmChkDate{font-size:12px;font-weight:700}
.tmChkSub{margin-top:2px;font-size:10px;color:var(--tm-muted)}
.tmSumBtn{width:100%;padding:6px 4px;border:1px solid transparent;border-radius:7px;background:none;color:inherit;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
.tmSumBtn:hover{background:#171c23;border-color:#66501d}

.tmFuel{border:1px solid var(--tm-line);border-radius:9px;background:var(--tm-group);padding:6px 9px}
.tmFuel b{display:block;font-size:12px;font-weight:700}
.tmFuel i{display:block;margin-top:2px;font-style:normal;font-size:9.5px;color:var(--tm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.tmBal{font-size:13px;font-weight:800}
.tmCellNeg{background:var(--tm-badbg)!important;color:var(--tm-bad)!important}
.tmCellOk{color:var(--tm-good)}

.tmTileGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}
.tmTile{border:1px solid var(--tm-line);border-radius:8px;background:var(--tm-group);padding:5px 7px;min-width:0}
.tmTileLb{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--tm-muted)}
.tmTileVal{margin-top:1px;font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tmTile.bad .tmTileVal{color:var(--tm-bad)}
.tmTile.good .tmTileVal{color:var(--tm-good)}

.tmEmpty{padding:56px 16px;text-align:center;font-size:13px;color:var(--tm-muted)}

/* модалка чеков */
.tmModalBg{position:fixed;inset:0;z-index:220;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(0,0,0,.78);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px)}
.tmModal{width:100%;max-width:780px;border:1px solid var(--tm-line);border-radius:16px;background:#10141a;color:#edf1f7;box-shadow:0 30px 90px rgba(0,0,0,.55);display:flex;flex-direction:column;max-height:88vh}
.tmModalHead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:16px 18px 12px}
.tmModalHead h3{margin:0;font-size:17px;font-weight:800}
.tmModalHead p{margin:3px 0 0;font-size:11.5px;color:var(--tm-muted)}
.tmModalX{border:0;background:none;color:var(--tm-muted);font-size:24px;line-height:1;cursor:pointer}
.tmModalX:hover{color:#fff}
.tmModalScroll{margin:0 18px;overflow:auto;border:1px solid var(--tm-line);border-radius:12px}
.tmModalTable{width:100%;border-collapse:collapse;font-size:13px}
.tmModalTable thead th{position:sticky;top:0;background:#0d1116;border-bottom:1px solid var(--tm-line);padding:9px 12px;text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--tm-muted)}
.tmModalTable tbody td{border-bottom:1px solid var(--tm-line);padding:9px 12px;vertical-align:top}
.tmModalTable tbody tr:last-child td{border-bottom:0}
.tmModalTable b{font-weight:700}
.tmModalTable i{font-style:normal;color:var(--tm-muted)}
.tmRight{text-align:right}
.tmLink{border:0;background:none;color:var(--tm-muted);font:inherit;font-size:12px;cursor:pointer}
.tmLink:hover{color:var(--tm-accent)}
.tmEmptyRow{padding:26px 12px!important;text-align:center;color:var(--tm-muted)}
.tmModalFoot{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;padding:14px 18px 16px}
.tmModalTot{font-size:12px;color:var(--tm-muted)}
.tmModalTot b{color:#edf1f7;font-weight:700}
.tmModalTot b.neg{color:var(--tm-bad)}
.tmBtnAccent{border:0;border-radius:9px;background:var(--tm-accent);color:#000;font-weight:800;font-size:13px;padding:9px 16px;cursor:pointer}
.tmBtnAccent:hover{filter:brightness(1.1)}

@media (max-width:1400px){ .tmKpis{grid-template-columns:repeat(4,minmax(0,1fr))} }
@media (max-width:900px){
  .tmWrap{padding:10px}
  .tmKpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-bottom:10px}
  .tmKpi{padding:9px 10px}
  .tmKpiVal{font-size:17px}
  .tmNote{font-size:11px}
  .tmModal{max-height:92vh}
  .tmModalScroll{margin:0 12px}
  .tmModalHead,.tmModalFoot{padding-left:12px;padding-right:12px}
  .tmBtnAccent{width:100%}
}

/* ===== asdNB: палитра для модалки чеков (она fixed и живёт вне потока) ===== */
.tmModalBg{
  --tm-line:#2a313b;--tm-muted:#8b95a5;--tm-accent:#f5b72f;
  --tm-bad:#ff9b9b;--tm-good:#b9e8c5
}
.tmModalTable tbody tr:hover td{background:#141a22}

/* ===== asdNC: час пик — нормальная сетка вместо сплюснутого полукруга ===== */
.fixPeakHero{grid-template-columns:minmax(150px,auto) minmax(0,1fr) minmax(0,auto);grid-template-areas:"main chart top";align-items:center;gap:14px 20px;padding:14px 18px;border-radius:20px}
.fixPeakChart{grid-area:chart;display:flex;flex-direction:column;gap:4px;min-width:0}
.fixPeakBars{grid-area:auto;height:62px;gap:2px}
.fixPeakBar{border-radius:3px 3px 0 0;background:rgba(255,255,255,.13)}
.fixPeakAxis{display:flex;justify-content:space-between;font-size:9.5px;font-weight:700;letter-spacing:.03em;color:var(--text-muted)}
.fixPeakTop{grid-area:top;flex-direction:column;align-items:flex-start;gap:4px;padding-left:14px;border-left:1px solid var(--border)}
.fixPeakTop u{font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;text-decoration:none;color:var(--text-muted)}
.fixPeakChip{padding:2px 9px}
@media (max-width:900px){
  .fixPeakHero{grid-template-columns:minmax(0,1fr);grid-template-areas:"main" "chart" "top";align-items:stretch;gap:10px;border-radius:18px}
  .fixPeakTop{flex-direction:row;flex-wrap:wrap;padding-left:0;border-left:0;border-top:1px solid var(--border);padding-top:8px}
  .fixPeakBars{height:48px}
  .fixPeakVal{font-size:26px}
}

/* ===== asdNC: источники заказов ===== */
.srcTableWrap{overflow-x:auto;border:1px solid var(--border);border-radius:12px;-webkit-overflow-scrolling:touch}
.srcTbl,.srcDayTbl{width:100%;border-collapse:collapse;font-size:12px;font-variant-numeric:tabular-nums}
.srcTbl th,.srcDayTbl th{background:var(--sink-1,rgba(0,0,0,.22));font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--text-muted);text-align:center;padding:8px 10px;border-bottom:1px solid var(--border)}
.srcTbl td,.srcDayTbl td{padding:8px 10px;border-bottom:1px solid color-mix(in srgb,var(--border) 55%,transparent)}
.srcTbl tbody tr:hover td,.srcDayTbl tbody tr:hover td{background:color-mix(in srgb,var(--accent,#f0b429) 6%,transparent)}
.srcTbl th:first-child,.srcTblName{text-align:left}
.srcTblName b{font-size:12.5px;font-weight:700}
.srcTblNum{text-align:center;font-weight:700}
.srcTblCpo{color:var(--yellow-text,#ffe7a8)}
.srcTbl tfoot td{background:var(--sink-1,rgba(0,0,0,.22));border-top:1px solid var(--border);border-bottom:0;font-weight:800}
.srcDim{color:var(--text-muted);opacity:.6}
.srcCnt{min-width:30px;padding:2px 8px;border:1px solid var(--border);border-radius:8px;background:transparent;color:var(--text);font:inherit;font-weight:800;cursor:pointer}
.srcCnt:hover{border-color:var(--accent,#f0b429);color:var(--accent,#f0b429)}
.srcCnt.strong{background:color-mix(in srgb,var(--accent,#f0b429) 16%,transparent);border-color:transparent}

.srcDayTbl{min-width:640px}
.srcDayG th{border-right:1px solid var(--border)}
.srcDayG2 th{font-size:9px;font-weight:700;text-transform:none;letter-spacing:0;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.srcDayDate{position:sticky;left:0;z-index:2;background:var(--bg-elevated,#141a24)!important;text-align:left!important;min-width:64px}
.srcDayDate b{display:block;font-size:12px;font-weight:800}
.srcDayDate i{display:block;font-style:normal;font-size:9px;font-weight:700;text-transform:uppercase;color:var(--text-muted)}
.srcDayCell{text-align:center;vertical-align:middle}
.srcDayZero{background:repeating-linear-gradient(135deg,transparent,transparent 6px,color-mix(in srgb,var(--border) 18%,transparent) 6px,color-mix(in srgb,var(--border) 18%,transparent) 7px)}
.srcDayBud{display:block;margin-top:2px;font-style:normal;font-size:9px;color:var(--text-muted)}
.srcDayTbl tfoot td,.srcDayTbl tfoot th{background:var(--sink-1,rgba(0,0,0,.22));border-top:1px solid var(--border);font-weight:800}
.srcNote{margin-top:10px;font-size:10.5px;line-height:1.55;color:var(--text-muted)}

/* всплывающий список заказов */
.srcPickWrap{position:fixed;inset:0;z-index:95;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(0,0,0,.72);-webkit-backdrop-filter:blur(5px);backdrop-filter:blur(5px)}
.srcPick{width:100%;max-width:760px;max-height:86vh;display:flex;flex-direction:column;border:1px solid var(--border);border-radius:16px;background:var(--bg-elevated,#141a24);box-shadow:0 30px 90px rgba(0,0,0,.55)}
.srcPickHead{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 10px}
.srcPickHead h4{margin:0;font-size:15px;font-weight:800}
.srcPickHead p{margin:2px 0 0;font-size:11px;color:var(--text-muted)}
.srcPickScroll{margin:0 16px 16px;overflow:auto;border:1px solid var(--border);border-radius:12px}
.srcPickTbl{width:100%;border-collapse:collapse;font-size:12px}
.srcPickTbl thead th{position:sticky;top:0;background:var(--sink-1,rgba(10,12,16,.98));padding:8px 10px;text-align:left;font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:var(--text-muted);border-bottom:1px solid var(--border)}
.srcPickTbl td{padding:8px 10px;border-bottom:1px solid color-mix(in srgb,var(--border) 55%,transparent);vertical-align:top}
.srcPickTbl tbody tr:last-child td{border-bottom:0}
.srcPickTime b{font-weight:800}
.srcPickTime i{display:block;font-style:normal;font-size:9.5px;color:var(--text-muted)}
.srcPickAddr{max-width:340px}
.srcPickAddr b{display:block;font-weight:600;line-height:1.35}
.srcPickAddr i{display:block;margin-top:2px;font-style:normal;font-size:10.5px;color:var(--text-muted);line-height:1.35}
.srcPickSum{text-align:right;font-weight:800;white-space:nowrap}
.srcReg,.srcStat{display:inline-block;padding:2px 8px;border-radius:999px;font-size:9.5px;font-weight:800;white-space:nowrap}
.srcReg--msk{background:rgba(240,180,41,.16);color:var(--yellow-text,#ffe7a8)}
.srcReg--mo{background:rgba(120,150,255,.14);color:#9fb4ff}
.srcReg--unknown{background:rgba(255,255,255,.06);color:var(--text-muted)}
.srcStat--completed{background:rgba(60,200,140,.14);color:var(--green-text,#7ee2b8)}
.srcStat--in_progress{background:rgba(240,180,41,.14);color:var(--yellow-text,#ffe7a8)}
.srcStat--scheduled{background:rgba(120,150,255,.14);color:#9fb4ff}
.srcStat--new{background:rgba(255,255,255,.06);color:var(--text-muted)}
@media (max-width:900px){
  .srcPick{max-height:92vh}
  .srcPickScroll{margin:0 10px 12px}
  .srcPickHead{padding:12px 12px 8px}
  .srcPickAddr{max-width:200px}
}

/* ===== asdND: колонка «н/д» в разрезе регионов ===== */
.srcDayNd{color:var(--text-muted)}

/* ===== asdNE: источники на узких экранах ===== */
.srcLog .dealMtxHead{flex-wrap:wrap}
.srcLog .dealMtxHead>div{min-width:0}
.srcLog .dealMtxHead p{white-space:normal;overflow-wrap:anywhere}
.srcSect,.srcSectHead,.srcNote{min-width:0;max-width:100%}
.srcNote{overflow-wrap:anywhere}
.srcTbl{min-width:600px}
.srcDayG2 th{max-width:none;white-space:nowrap}
@media (max-width:720px){
  .srcSectHead span{display:none}
  .srcDayDate{min-width:56px}
  .srcTbl th,.srcTbl td,.srcDayTbl th,.srcDayTbl td{padding:7px 8px}
}

/* ===== asdNF: фиксация заказов — прокрутка и телефон ===== */
.fixHrChart .fixHrCol{border:0;padding:0;background:transparent;font:inherit;color:inherit;cursor:pointer}
.fixHrChart .fixHrCol.zero{cursor:default}
.fixHrTable tbody tr.hit{cursor:pointer}
.fixHrTable tbody tr.hit:hover td{background:color-mix(in srgb,var(--accent,#f0b429) 12%,transparent)}
.fixHoursHead{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap}
.fixHrSeg{flex:0 0 auto}
.fixHrHint{margin:8px 0 10px;font-size:10.5px;color:var(--text-muted)}

/* карта «дни × часы» */
.fixHeatScroll{overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:4px}
.fixHeat{display:flex;flex-direction:column;gap:3px;min-width:620px}
.fixHeatRow{display:grid;grid-template-columns:62px repeat(24,minmax(0,1fr)) 44px;gap:3px;align-items:center}
.fixHeatDate{display:flex;flex-direction:column;line-height:1.15;font-variant-numeric:tabular-nums}
.fixHeatDate b{font-size:11px;font-weight:800}
.fixHeatDate i{font-style:normal;font-size:8.5px;font-weight:700;text-transform:uppercase;color:var(--text-muted)}
.fixHeatAxis{padding-bottom:2px}
.fixHeatTick{text-align:center;font-size:8.5px;font-weight:700;color:var(--text-muted);font-variant-numeric:tabular-nums}
.fixHeatTot{text-align:right;font-size:10.5px;font-weight:800;color:var(--text-muted);font-variant-numeric:tabular-nums}
.fixHeatCell{aspect-ratio:1/1;min-height:18px;padding:0;border:1px solid transparent;border-radius:5px;background:rgba(255,255,255,.045);color:var(--text);font:inherit;font-size:9.5px;font-weight:800;line-height:1;cursor:default;font-variant-numeric:tabular-nums}
