.fixHpCard>header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px 10px;border-bottom:1px solid var(--border)}
.fixHpCard>header b{display:block;font-size:17px;font-weight:800;letter-spacing:-.3px;font-variant-numeric:tabular-nums}
.fixHpCard>header span{display:block;margin-top:2px;font-size:11px;color:var(--text-muted)}
.fixHpCard>header button{border:1px solid var(--border);background:transparent;color:var(--text-muted);border-radius:10px;padding:5px 7px;cursor:pointer}
.fixHpList{overflow:auto;padding:8px 10px 12px;display:flex;flex-direction:column;gap:6px}
.fixHpRow{display:grid;grid-template-columns:54px minmax(0,1fr) auto;gap:10px;align-items:center;padding:8px 10px;border:1px solid var(--border);border-radius:12px;background:var(--sink-1,rgba(0,0,0,.18))}
.fixHpRow.partner{border-color:color-mix(in srgb,var(--accent,#f0b429) 40%,var(--border))}
.fixHpTime b{font-size:13px;font-weight:800;font-variant-numeric:tabular-nums}
.fixHpTime i{display:block;font-style:normal;font-size:9.5px;color:var(--text-muted)}
.fixHpMain{min-width:0}
.fixHpMain b{display:block;font-size:12.5px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fixHpMain i{display:block;font-style:normal;font-size:10.5px;color:var(--text-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fixHpSide{display:flex;flex-direction:column;align-items:flex-end;gap:3px;white-space:nowrap}
.fixHpSide b{font-size:13px;font-weight:800;font-variant-numeric:tabular-nums}

@media (max-width:900px){
