  .fixTable td[data-l="Авто клиента"],.fixTable td[data-l="Техника"]{grid-column:1/-1}
  .fixTable tbody tr.partner{border-color:color-mix(in srgb,var(--accent,#f0b429) 40%,var(--border))}

  .fixHeatRow{grid-template-columns:54px repeat(24,minmax(0,1fr)) 38px}
  .fixHpCard{max-height:88vh}
  .fixHpRow{grid-template-columns:46px minmax(0,1fr);gap:6px 8px}
  .fixHpSide{grid-column:2;flex-direction:row;align-items:center;justify-content:space-between}
}
