.driverOrderHint.technoprimeHint{border-color:rgba(240,180,41,.35);background:rgba(240,180,41,.1);color:#ffe7a8}

/* asdOL: карандаш в приёме кассы */
.kbHandInTop{display:flex;align-items:center;justify-content:space-between;gap:6px;width:100%}
.kbHandInCell .kbPencil,.kbCell .kbPencil{width:26px;height:26px;flex:0 0 auto;opacity:.75}
.kbHandInCell .kbPencil:hover,.kbCell .kbPencil:hover{opacity:1;border-color:rgba(240,180,41,.45);color:#f0b429}
.kbCell{display:flex;flex-direction:column;gap:4px;align-items:stretch}


.vodkaView{display:flex;flex-direction:column;gap:12px;width:100%;padding:8px 8px 24px;box-sizing:border-box}
.vodkaToolbar{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:12px;padding:4px 4px 0}
.vodkaBrand{display:flex;flex-direction:column;gap:2px}
.vodkaBrand strong{font-size:1.05rem;letter-spacing:.01em}
.vodkaBrand span{color:var(--text-muted);font-size:.82rem}
.vodkaPeriod{display:flex;flex-wrap:wrap;align-items:flex-end;gap:8px}
.vodkaPeriod label{display:flex;flex-direction:column;gap:3px;font-size:.75rem;color:var(--text-muted)}
.vodkaPeriod input{border-radius:10px;border:1px solid var(--border);background:var(--sink-1,rgba(0,0,0,.22));color:var(--text);padding:7px 10px;font:inherit}
.vodkaErr{color:#ff8f8f;padding:8px 12px;border-radius:12px;background:rgba(170,40,40,.15);border:1px solid rgba(255,120,120,.25)}
.vodkaPage{display:flex;justify-content:center;width:100%}
.vodkaSheet{
  width:min(980px,100%);
  min-height:min(680px,70vh);
  aspect-ratio:297/210;
  max-height:none;
  box-sizing:border-box;
  padding:16px 18px 18px;
  border-radius:14px;
  color:#e8eaed;
  background:
    radial-gradient(120% 90% at 0% 0%,rgba(255,255,255,.04),transparent 50%),
    radial-gradient(90% 70% at 100% 0%,rgba(240,180,41,.08),transparent 45%),
    linear-gradient(180deg,#151920 0%,#0d1015 100%);
  border:1px solid rgba(255,255,255,.08);
  box-shadow:0 18px 40px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.04);
  display:flex;flex-direction:column;gap:10px;overflow:auto;
}
.vodkaSheetHead{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.vodkaEyebrow{font-size:.68rem;letter-spacing:.14em;text-transform:uppercase;color:rgba(240,180,41,.75);margin-bottom:2px}
.vodkaSheetHead h2{margin:0;font-size:1.2rem;font-weight:700;letter-spacing:.01em}
.vodkaSheetPeriod{font-size:.8rem;color:rgba(232,234,237,.65);padding-top:4px;white-space:nowrap}
.vodkaEmpty{padding:40px 12px;text-align:center;color:rgba(232,234,237,.55)}
.vodkaTopRow,.vodkaRevRow{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:8px}
.vodkaCard{
  border-radius:14px;padding:10px 12px;
  background:rgba(255,255,255,.035);
  border:1px solid rgba(255,255,255,.07);
  box-shadow:0 6px 16px rgba(0,0,0,.2);
  display:flex;flex-direction:column;gap:4px;min-width:0;
}
.vodkaCard--partner{border-color:rgba(168,130,255,.28);background:linear-gradient(180deg,rgba(120,90,200,.14),rgba(255,255,255,.03))}
.vodkaCard--total{border-color:rgba(240,180,41,.35);background:linear-gradient(180deg,rgba(240,180,41,.12),rgba(255,255,255,.03))}
.vodkaCard--rev{grid-column:auto}
.vodkaCardLb{font-size:.72rem;color:rgba(232,234,237,.62);letter-spacing:.02em}
.vodkaCardVal{font-size:1.25rem;font-weight:750;font-variant-numeric:tabular-nums;line-height:1.15}
.vodkaHint{font-size:.68rem;color:rgba(232,234,237,.45);line-height:1.3}
.vodkaRule{height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.18),transparent);margin:2px 0}
.vodkaMiniRow{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:6px}
.vodkaMetric{display:flex;flex-direction:column;gap:1px;padding:6px 8px;border-radius:10px;background:rgba(0,0,0,.22);border:1px solid rgba(255,255,255,.05)}
.vodkaMetric span{font-size:.65rem;color:rgba(232,234,237,.55);text-transform:lowercase}
.vodkaMetric b{font-size:.82rem;font-weight:650;font-variant-numeric:tabular-nums}
.vodkaMetric--money b{color:#f0d08a}
.vodkaSection{display:flex;flex-direction:column;gap:6px}
.vodkaSection h3{margin:0;font-size:.78rem;letter-spacing:.08em;text-transform:uppercase;color:rgba(232,234,237,.55);font-weight:650}
.vodkaGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.vodkaTile{
  border-radius:12px;padding:8px 9px;
  background:rgba(255,255,255,.03);
  border:1px solid rgba(255,255,255,.07);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.03);
  min-width:0;
}
.vodkaTile--disp{border-color:rgba(100,180,255,.18)}
.vodkaTile header{font-size:.78rem;font-weight:700;margin-bottom:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vodkaTileGrid{display:grid;grid-template-columns:1fr 1fr;gap:5px}
.vodkaExpense{
  border-radius:14px;padding:10px 12px;display:flex;flex-direction:column;gap:8px;
  background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);
}
.vodkaExpFuel .vodkaTileGrid{grid-template-columns:repeat(3,minmax(0,1fr))}
.vodkaExpRest{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.vodkaNet{
  margin-top:2px;display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:10px 12px;border-radius:999px;
  background:linear-gradient(90deg,rgba(240,180,41,.16),rgba(255,255,255,.04));
  border:1px solid rgba(240,180,41,.3);
}
.vodkaNet span{font-size:.8rem;color:rgba(232,234,237,.7);letter-spacing:.04em;text-transform:uppercase}
.vodkaNet b{font-size:1.15rem;font-weight:800;font-variant-numeric:tabular-nums;color:#f0d08a}
@media (max-width:900px){
  .vodkaSheet{aspect-ratio:auto;min-height:0}
  .vodkaTopRow,.vodkaRevRow{grid-template-columns:1fr}
  .vodkaGrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .vodkaExpRest{grid-template-columns:1fr}
}

/* asdOP: фиксация KPI — читаемые названия */
