/* ===== asdSp: сводка недели — redesign ===== */
.vodkaView{padding:6px 0 24px}
.vodkaPage{padding:0 2px;display:flex;justify-content:center}
.vodkaSheet{
  width:min(1120px,100%);
  min-height:740px;
  aspect-ratio:297/210;
  box-sizing:border-box;
  padding:26px 30px 24px;
  gap:12px;
  border-radius:20px;
  color:#eef1f6;
  background:
    radial-gradient(70% 55% at 0% 0%,rgba(240,180,41,.11),transparent 50%),
    radial-gradient(55% 45% at 100% 8%,rgba(110,150,255,.1),transparent 48%),
    radial-gradient(40% 35% at 80% 100%,rgba(168,130,255,.06),transparent 50%),
    linear-gradient(165deg,#141a22 0%,#0c1016 48%,#090b10 100%);
  border:1px solid rgba(255,255,255,.1);
  box-shadow:
    0 28px 60px rgba(0,0,0,.55),
    inset 0 1px 0 rgba(255,255,255,.06),
    inset 0 0 0 1px rgba(240,180,41,.04);
  display:flex;flex-direction:column;overflow:auto;
  position:relative;
}
.vodkaSheet::before{
  content:"";position:absolute;inset:10px;border-radius:14px;pointer-events:none;
  border:1px solid rgba(255,255,255,.035);
}
.vodkaSheetHead{
  display:flex;align-items:flex-start;justify-content:space-between;gap:18px;
  padding:0 0 14px;margin:0;
  border-bottom:1px solid transparent;
  border-image:linear-gradient(90deg,transparent,rgba(240,180,41,.45),rgba(255,255,255,.12),transparent) 1;
